import React from 'react';
import './personalInfo.css';

function PersonalInfo() {
  return (
    <section id="personal-info" className="section">
      <h2>Personal Information</h2>
      <p><strong>Name:</strong> Srihari Pentakota</p>
      <p><strong>Title:</strong> Associate Analyst</p>
      <p><strong>Organization:</strong> Deloitte Consulting India Pvt Ltd</p>
      <p><strong>Location:</strong> Hyderabad, Telangana</p>
      <p><strong>Email:</strong> sesrihari@deloitte.com</p>
      <p><strong>Mobile:</strong> +91 6281997025</p>
    </section>
  );
}

export default PersonalInfo;
